"""bc7.py - BC7 (BPTC) dekoder u cistom Pythonu (za teksture dresova iz igre). decode(data, w, h) -> RGBA bytearray."""
P2 = [int(c) for c in '']
P3 = [int(c) for c in '']
A2 = [15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 2, 8, 2, 2, 8, 8, 15, 2, 8, 2, 2, 8, 8, 2, 2,
      15, 15, 6, 8, 2, 8, 15, 15, 2, 8, 2, 2, 2, 15, 15, 6, 6, 2, 6, 8, 15, 15, 2, 2, 15, 15, 15, 15, 15, 2, 2, 15]
A3a = [3, 3, 15, 15, 8, 3, 15, 15, 8, 8, 6, 6, 6, 5, 3, 3, 3, 3, 8, 15, 3, 3, 6, 10, 5, 8, 8, 6, 8, 5, 15, 15,
       8, 15, 3, 5, 6, 10, 8, 15, 15, 3, 15, 5, 15, 15, 15, 15, 3, 15, 5, 5, 5, 8, 5, 10, 5, 10, 8, 13, 15, 12, 3, 3]
A3b = [15, 8, 8, 3, 15, 15, 3, 8, 15, 15, 15, 15, 15, 15, 15, 8, 15, 8, 15, 3, 15, 8, 15, 8, 3, 15, 6, 10, 15, 15, 10, 8,
       15, 3, 15, 10, 10, 8, 9, 10, 6, 15, 8, 15, 3, 6, 6, 8, 15, 3, 15, 15, 15, 15, 15, 15, 15, 15, 15, 15, 3, 15, 15, 8]
W = {2: [0, 21, 43, 64], 3: [0, 9, 18, 27, 37, 46, 55, 64], 4: [0, 4, 9, 13, 17, 21, 26, 30, 34, 38, 43, 47, 51, 55, 60, 64]}
#        NS PB RB ISB CB AB EPB SPB IB IB2
MODES = [(3, 4, 0, 0, 4, 0, 1, 0, 3, 0), (2, 6, 0, 0, 6, 0, 0, 1, 3, 0), (3, 6, 0, 0, 5, 0, 0, 0, 2, 0), (2, 6, 0, 0, 7, 0, 1, 0, 2, 0),
         (1, 0, 2, 1, 5, 6, 0, 0, 2, 3), (1, 0, 2, 0, 7, 8, 0, 0, 2, 2), (1, 0, 0, 0, 7, 7, 1, 0, 4, 0), (2, 6, 0, 0, 5, 5, 1, 0, 2, 0)]


def _unq(v, n):
    v <<= (8 - n)
    return v | (v >> n)


def block(b):
    """16 piksela (r, g, b, a) iz 16 B bloka."""
    x = int.from_bytes(b, 'little')
    if not x & 0xff:
        return [(0, 0, 0, 0)] * 16
    m = (x & -x).bit_length() - 1
    if m > 7:
        return [(0, 0, 0, 0)] * 16
    ns, pb, rb, isb, cb, ab, epb, spb, ib, ib2 = MODES[m]
    pos = m + 1

    def rd(n):
        nonlocal pos
        v = (x >> pos) & ((1 << n) - 1)
        pos += n
        return v
    part = rd(pb)
    rot = rd(rb)
    isel = rd(isb)
    ne = ns * 2
    col = [[rd(cb) for _ in range(ne)] for _c in range(3)]
    alp = [rd(ab) for _ in range(ne)] if ab else None
    if epb:
        pbits = [rd(1) for _ in range(ne)]
    elif spb:
        sp = [rd(1) for _ in range(ns)]
        pbits = [sp[e >> 1] for e in range(ne)]
    else:
        pbits = None
    cbn, abn = cb + (1 if pbits else 0), ab + (1 if pbits else 0)
    ep = []
    for e in range(ne):
        p = pbits[e] if pbits else 0
        r = _unq((col[0][e] << 1 | p) if pbits else col[0][e], cbn)
        g = _unq((col[1][e] << 1 | p) if pbits else col[1][e], cbn)
        bb = _unq((col[2][e] << 1 | p) if pbits else col[2][e], cbn)
        a = _unq((alp[e] << 1 | p) if pbits else alp[e], abn) if alp else 255
        ep.append((r, g, bb, a))
    if ns == 1:
        sub = [0] * 16
        anc = (0,)
    elif ns == 2:
        sub = P2[part * 16:part * 16 + 16]
        anc = (0, A2[part])
    else:
        sub = P3[part * 16:part * 16 + 16]
        anc = (0, A3a[part], A3b[part])
    idx = [rd(ib - 1 if i in anc else ib) for i in range(16)]
    idx2 = [rd(ib2 - 1 if i == 0 else ib2) for i in range(16)] if ib2 else None
    out = []
    for i in range(16):
        s = sub[i]
        e0, e1 = ep[2 * s], ep[2 * s + 1]
        if idx2 is None:
            w = W[ib][idx[i]]
            wa = w
        elif isel:
            w, wa = W[ib2][idx2[i]], W[ib][idx[i]]
        else:
            w, wa = W[ib][idx[i]], W[ib2][idx2[i]]
        r = ((64 - w) * e0[0] + w * e1[0] + 32) >> 6
        g = ((64 - w) * e0[1] + w * e1[1] + 32) >> 6
        bb = ((64 - w) * e0[2] + w * e1[2] + 32) >> 6
        a = ((64 - wa) * e0[3] + wa * e1[3] + 32) >> 6
        if rot == 1:
            r, a = a, r
        elif rot == 2:
            g, a = a, g
        elif rot == 3:
            bb, a = a, bb
        out.append((r, g, bb, a))
    return out


def decode(data, w, h):
    out = bytearray(w * h * 4)
    bw, bh = (w + 3) // 4, (h + 3) // 4
    o = 0
    for by in range(bh):
        for bx in range(bw):
            px = block(data[o:o + 16])
            o += 16
            for i in range(16):
                xx, yy = bx * 4 + (i & 3), by * 4 + (i >> 2)
                if xx < w and yy < h:
                    q = (yy * w + xx) * 4
                    out[q:q + 4] = bytes(px[i])
    return out
